const objectOrEmpty=value=>value&&typeof value==="object"&&!Array.isArray(value)?value:{};
function normalizeWorkbook(raw){
  const clean=emptyWorkbook();if(!raw||typeof raw!=="object")return clean;
  const styles=objectOrEmpty(raw.styles),mindsetValues=objectOrEmpty(raw.mindsets),body=objectOrEmpty(raw.body),scenarioValues=objectOrEmpty(raw.scenarios),choices=objectOrEmpty(raw.choices);
  styleQuestions.forEach(([id])=>{const value=Number(styles[id]);if([1,2,3,4].includes(value))clean.styles[id]=value});
  mindsets.forEach(({id})=>{const value=Number(mindsetValues[id]);if([1,2,3,4].includes(value))clean.mindsets[id]=value});
  mechanics.forEach(({id})=>{if(["Needs practice","Developing","Usually confident"].includes(body[id]))clean.body[id]=body[id]});
  if(Number(raw.version)>=3)scenarios.forEach(({id})=>{const value=Number(scenarioValues[id]);if([0,1,2,3].includes(value))clean.scenarios[id]=value});
  if(typeof choices.presenceChoice==="string")clean.choices.presenceChoice=choices.presenceChoice;
  if(pages.includes(raw.lastPage))clean.lastPage=raw.lastPage;
  if(typeof raw.updatedAt==="string")clean.updatedAt=raw.updatedAt;
  return clean;
}
function answerCount(){return Object.keys(workbook.mindsets).length+Object.keys(workbook.body).length+Object.keys(workbook.styles).length+Object.keys(workbook.scenarios).length+Object.keys(workbook.choices).length}
function setSaveNotice(message,type=""){const notice=document.getElementById("saveNotice");if(!notice)return;notice.textContent=message;notice.classList.toggle("save-error",type==="error");notice.classList.toggle("save-restored",type==="restored")}
function loadSaved(){try{const raw=localStorage.getItem(storageKey);if(!raw)return;workbook=normalizeWorkbook(JSON.parse(raw));restoredSession=answerCount()>0}catch{storageWorks=false}}
function save({quiet=false}={}){workbook.version=3;workbook.updatedAt=new Date().toISOString();try{localStorage.setItem(storageKey,JSON.stringify(workbook));storageWorks=true;if(!quiet)setSaveNotice(`✓ Saved ${answerCount()} responses on this device at ${new Date(workbook.updatedAt).toLocaleTimeString([],{hour:"numeric",minute:"2-digit"})}.`)}catch{storageWorks=false;setSaveNotice("Your browser is blocking local saving. Use Download Backup before leaving this course.","error")}}

function render(){
  document.getElementById("mindsetCards").innerHTML=mindsets.map((m,i)=>`<article><h2>${i+1}. ${m.title}</h2><p>${m.meaning}</p><strong>INTERVIEW VALUE</strong><p>${m.use}</p></article>`).join("");
  document.getElementById("mindsetQuestions").innerHTML=mindsets.map((m,i)=>ratingRow(`mindset-${m.id}`,`How useful would “${m.title}” be for you?`,i,workbook.mindsets[m.id])).join("");
  document.getElementById("mechanicCards").innerHTML=mechanics.map(m=>`<article><b>${m.icon}</b><h2>${m.title}</h2><p>${m.text}</p></article>`).join("");
  document.getElementById("bodyQuestions").innerHTML=mechanics.map(m=>`<div class="body-question"><p><strong>${m.title}</strong></p>${["Needs practice","Developing","Usually confident"].map(v=>`<label><input type="radio" name="body-${m.id}" value="${v}" ${workbook.body[m.id]===v?"checked":""}><span>${v}</span></label>`).join("")}</div>`).join("");
  document.getElementById("styleQuestions").innerHTML=styleQuestions.map((q,i)=>ratingRow(`style-${q[0]}`,q[2],i,workbook.styles[q[0]])).join("");
  document.getElementById("scenarioQuestions").innerHTML=scenarios.map((s,i)=>{
    const selected=workbook.scenarios[s.id],answered=Number.isInteger(selected),feedback=answered?s.feedback[selected]:null,level=answered?(feedback.score===3?"strong":feedback.score===2?"workable":"review"):"";
    const levelLabel=level==="strong"?"Strong response":level==="workable"?"Workable response":"Needs revision";
    return `<article class="scenario"><h2>${i+1}. ${s.question}</h2><p>Choose the response you would be most likely to use. Several answers may be reasonable, but each has different strengths and risks.</p><div class="scenario-options">${s.choices.map((c,j)=>`<label class="${selected===j?"selected":""}"><input type="radio" name="scenario-${s.id}" value="${j}" ${selected===j?"checked":""}><span>${String.fromCharCode(65+j)}</span><b>${c}</b></label>`).join("")}</div>${answered?`<div class="scenario-feedback ${level}"><div class="feedback-heading"><span>${feedback.score}/3</span><div><small>${levelLabel}</small><strong>${feedback.heading}</strong></div></div><p><b>What this may communicate:</b> ${feedback.impact}</p><p><b>How to improve or strengthen it:</b> ${feedback.coaching}</p><div class="sample-answer"><b>Practice saying:</b><q>${feedback.sample}</q></div></div>`:`<div class="scenario-feedback empty">Select an answer to receive a 1–3 rating, specific coaching, and a stronger sample response.</div>`}</article>`;
  }).join("");
  restoreSimpleChoices();bindInputs();updateStyleResult();updateSummary();
}
function ratingRow(name,text,index,value){return `<div class="rating-row"><p><span>${index+1}</span>${text}</p><div class="rating-options">${[1,2,3,4].map(n=>`<label><input type="radio" name="${name}" value="${n}" ${value===n?"checked":""}><span>${n}</span></label>`).join("")}</div></div>`}
function bindInputs(){
  document.querySelectorAll('input[name^="mindset-"]').forEach(el=>el.onchange=()=>{workbook.mindsets[el.name.replace("mindset-","")]=Number(el.value);save();updateSummary()});
  document.querySelectorAll('input[name^="body-"]').forEach(el=>el.onchange=()=>{workbook.body[el.name.replace("body-","")]=el.value;save();updateSummary()});
  document.querySelectorAll('input[name^="style-"]').forEach(el=>el.onchange=()=>{workbook.styles[el.name.replace("style-","")]=Number(el.value);save();updateStyleResult();updateSummary()});
  document.querySelectorAll('input[name^="scenario-"]').forEach(el=>el.onchange=()=>{workbook.scenarios[el.name.replace("scenario-","")]=Number(el.value);save();render()});
  document.querySelectorAll('.choice input').forEach(el=>el.onchange=()=>{workbook.choices[el.name]=el.value;save();restoreSimpleChoices();updateSummary()});
}
function restoreSimpleChoices(){document.querySelectorAll('.choice input').forEach(el=>{el.checked=workbook.choices[el.name]===el.value;el.closest("label").classList.toggle("selected",el.checked)})}
function styleScores(){return Object.keys(styleInfo).map(key=>{const related=styleQuestions.filter(q=>q[1]===key),total=related.reduce((sum,q)=>sum+(workbook.styles[q[0]]||0),0);return{key,total,average:total/related.length}}).sort((a,b)=>b.total-a.total||a.key.localeCompare(b.key))}

function evenProfile(score,overall,scores){
  const profiles={
    1:{title:"Interview skills are at a starting point",description:"None of these behaviors feels consistent yet. That is useful information—not a failure. Build a basic routine before trying to identify a signature style.",strengths:["A clear starting point","An honest self-assessment","Every skill can be practiced"],watch:"Do not try to improve all 15 behaviors at once.",action:"Prepare one honest work example, record a 60-second introduction, and practice ending with a two-second pause.",kind:"starting"},
    2:{title:"Developing interview range",description:"You sometimes use all five strength styles, but none is dependable yet. Repetition—not a personality change—is the next step.",strengths:["Some access to every style","Balanced self-view","Room to choose a style intentionally"],watch:"Inconsistent skills may disappear when pressure rises.",action:"Record one answer twice: first naturally, then with a clear ending, one specific example, and a thoughtful pause.",kind:"developing"},
    3:{title:"Balanced and dependable interview style",description:"You use all five styles often. Your advantage is range: confidence, honesty, warmth, attention, and energy.",strengths:["Consistent range","Ability to adjust to the room","No obvious style gap"],watch:"Balanced answers can still sound generic without specific evidence.",action:"Prepare three examples: a result, a challenge, and a lesson learned.",kind:"balanced"},
    4:{title:"Versatile interview communicator",description:"You report using every interview strength consistently. The goal is refinement: match the room and support confidence with evidence.",strengths:["Strong range across all five styles","High reported confidence","Ability to create energy and trust"],watch:"A perfect self-rating can hide blind spots. Confirm it through a recorded mock interview or outside feedback.",action:"Record a mock interview and ask someone what felt strongest and what felt overused.",kind:"versatile"}
  };
  return{...profiles[score],scores,overall,priorityItems:[]};
}
function styleProfile(){
  if(Object.keys(workbook.styles).length!==styleQuestions.length)return null;
  const scores=styleScores(),overall=styleQuestions.reduce((sum,[id])=>sum+workbook.styles[id],0)/styleQuestions.length,spread=scores[0].total-scores.at(-1).total,values=new Set(styleQuestions.map(([id])=>workbook.styles[id]));
  const lowest=styleQuestions.map(([id,key,text])=>({id,key,text,value:workbook.styles[id]})).sort((a,b)=>a.value-b.value);
  if(values.size===1)return evenProfile(overall,overall,scores);
  if(spread<=1){const title=overall>=3.5?"Versatile interview communicator":overall>=2.75?"Balanced and dependable interview style":"Developing interview range";return{title,description:`Your five scores are nearly even. The result should not force a false label. Your overall average is ${overall.toFixed(1)} out of 4.`,strengths:["Range across several approaches","Potential to adapt to different interviewers","No single style dominates"],watch:"Build proof for your self-ratings through practice and outside feedback.",action:overall>=3?"Use a mock interview to confirm which style appears strongest to another person.":"Choose one low-rated behavior and repeat it in three recorded answers.",scores,overall,priorityItems:lowest.slice(0,3),kind:"balanced"}}
  const top=scores[0],second=scores[1],tied=scores.filter(s=>s.total===top.total),topInfo=styleInfo[top.key],secondInfo=styleInfo[second.key];
  return{title:tied.length>1?`Blended strengths: ${tied.slice(0,2).map(s=>styleInfo[s.key].name).join(" + ")}`:`${topInfo.name} with ${secondInfo.name} support`,description:tied.length>1?`Two styles share the lead. You are strongest when you combine ${tied.slice(0,2).map(s=>styleInfo[s.key].name.toLowerCase()).join(" and ")}.`:`${topInfo.description} Your secondary ${secondInfo.name.toLowerCase()} strength gives you another way to connect.`,strengths:[...topInfo.strengths,`Secondary strength: ${secondInfo.name}`],watch:topInfo.watch,action:topInfo.practice,scores,overall,priorityItems:lowest.slice(0,3),kind:"distinct"};
}
function scoreBars(scores){return `<div class="style-score-bars">${scores.map(s=>`<div><span>${styleInfo[s.key].name}</span><div><i style="width:${s.total/12*100}%"></i></div><strong>${s.total}/12</strong></div>`).join("")}</div>`}
function coachingList(profile){return profile.priorityItems.length?`<div class="coaching-panel"><h3>Your lowest-rated behaviors become the practice plan</h3><ol>${profile.priorityItems.map(item=>`<li><strong>${styleInfo[item.key].name} — rated ${item.value}:</strong> ${questionCoaching[item.id]}</li>`).join("")}</ol></div>`:`<p class="result-action"><strong>Best next move:</strong> ${profile.action}</p>`}
function updateStyleResult(){const box=document.getElementById("liveStyleResult"),count=Object.keys(workbook.styles).length;if(count<styleQuestions.length){box.innerHTML=`<strong>${count} of ${styleQuestions.length} completed.</strong><p>Finish every statement to receive a strength pattern, score comparison, watch-out, and specific practice plan.</p>`;return}const profile=styleProfile();box.innerHTML=`<p class="kicker">YOUR RESULT</p><h2>${profile.title}</h2><p>${profile.description}</p>${scoreBars(profile.scores)}<p><strong>Watch-out:</strong> ${profile.watch}</p>${coachingList(profile)}`}

function mindsetProfile(){
  if(Object.keys(workbook.mindsets).length<6)return null;
  const ranked=mindsets.map(m=>({...m,value:workbook.mindsets[m.id]})).sort((a,b)=>b.value-a.value),values=new Set(ranked.map(x=>x.value));
  if(values.size===1){const rating=ranked[0].value;if(rating===4)return{title:"All six mindsets feel essential",description:"There is no honest single winner. Turn them into a short routine.",action:"Use three cues: I will be okay; I will be honest; I will explore mutual fit."};if(rating===1)return{title:"No mindset stands out yet",description:"These ideas do not feel useful right now. Test one simple idea instead of forcing belief.",action:"Say: “This is a professional conversation, not a life-or-death test.”"};return{title:"The six mindsets are equally useful",description:`You rated every mindset ${rating} out of 4, so the result will not arbitrarily choose one.`,action:"Choose the one that addresses your biggest interview pressure and write it at the top of your notes."}}
  const leaders=ranked.filter(x=>x.value===ranked[0].value);if(leaders.length>1)return{title:`Top priorities: ${leaders.slice(0,2).map(x=>x.title).join(" + ")}`,description:"More than one mindset tied for your highest usefulness rating.",action:`Use “${leaders[0].title}” before the interview and “${leaders[1].title}” while answering.`};
  return{title:ranked[0].title,description:ranked[0].use,action:`Write this cue on your notes: “${ranked[0].title}.”`};
}
function scenarioProfile(){
  const completed=Object.keys(workbook.scenarios).length;
  const selected=scenarios.filter(s=>Number.isInteger(workbook.scenarios[s.id])).map(s=>{const choice=workbook.scenarios[s.id],feedback=s.feedback[choice];return{...s,choice,score:feedback.score,coaching:feedback.coaching}});
  const points=selected.reduce((sum,item)=>sum+item.score,0),possible=completed*3;
  const priorities=selected.filter(item=>item.score<3).sort((a,b)=>a.score-b.score).slice(0,3);
  if(!completed)return{points,possible,completed,priorities,label:"Not started",direction:"Complete the six scenarios. Every option provides a rating, explanation, and practice response."};
  if(completed<6)return{points,possible,completed,priorities,label:"In progress",direction:`Complete the remaining ${6-completed} scenarios. Your current score is ${points} of ${possible} available points.`};
  if(points>=16)return{points,possible:18,completed,priorities,label:"Strong interview judgment",direction:"You selected consistently strong or workable approaches. Practice the sample language aloud so it sounds natural rather than memorized."};
  if(points>=12)return{points,possible:18,completed,priorities,label:"Solid judgment with growth areas",direction:"Your choices are generally workable. Use the priority coaching below to make answers more direct, relevant, and convincing."};
  if(points>=8)return{points,possible:18,completed,priorities,label:"Developing interview judgment",direction:"Several choices could create avoidable employer concerns. Practice the improved responses before your next interview."};
  return{points,possible:18,completed,priorities,label:"Needs targeted practice",direction:"Work through the sample responses and repeat the lab after practicing them aloud."};
}
function updateSummary(){
  const styleCount=Object.keys(workbook.styles).length,mindsetCount=Object.keys(workbook.mindsets).length,bodyCount=Object.keys(workbook.body).length,profile=styleProfile(),mindset=mindsetProfile(),scenario=scenarioProfile();
  const bodyNeeds=mechanics.filter(m=>workbook.body[m.id]==="Needs practice"),practiceTargets=(bodyNeeds.length?bodyNeeds:mechanics.filter(m=>workbook.body[m.id]==="Developing")).slice(0,3);
  const actions=[mindset?mindset.action:"Complete the mindset ratings and choose one mental cue.",practiceTargets[0]?`Record one answer while practicing “${practiceTargets[0].title}.”`:"Choose one body-language skill to practice on video.",profile?profile.action:"Complete the strength-style statements for a targeted practice step."];
  document.getElementById("summaryContent").innerHTML=`
    <div class="summary-progress"><strong>${answerCount()} saved responses</strong><span>Mindsets ${mindsetCount}/6 • Body language ${bodyCount}/6 • Strength style ${styleCount}/15 • Practice ${scenario.completed}/6</span></div>
    <div class="summary-grid"><article class="summary-card highlight"><p class="kicker">MY INTERVIEW PATTERN</p><h2>${profile?profile.title:"Assessment not complete"}</h2><p>${profile?profile.description:`Complete all 15 statements (${styleCount}/15 completed).`}</p></article><article class="summary-card alert"><p class="kicker">MY MINDSET DIRECTION</p><h2>${mindset?mindset.title:"Assessment not complete"}</h2><p>${mindset?mindset.description:`Complete all six ratings (${mindsetCount}/6 completed).`}</p></article></div>
    <article class="summary-card"><h2>Strengths and Growth Direction</h2>${profile?`<ul>${profile.strengths.map(x=>`<li>${x}</li>`).join("")}</ul><p><strong>Watch-out:</strong> ${profile.watch}</p>${scoreBars(profile.scores)}${coachingList(profile)}`:"<p>Complete Module 4 to compare all five styles and build a plan from your lowest-rated behaviors.</p>"}</article>
    <article class="summary-card"><h2>Body-Language Practice</h2><p>${bodyCount}/6 skills reviewed.</p>${practiceTargets.length?`<ul>${practiceTargets.map(x=>`<li><strong>${x.title}:</strong> ${x.text}</li>`).join("")}</ul>`:"<p>Complete Module 3 or continue practicing all six skills.</p>"}</article>
    <article class="summary-card good"><h2>Practice-Lab Result: ${scenario.label}</h2><p><strong>${scenario.points} of ${scenario.possible||18} available points across ${scenario.completed} of 6 scenarios.</strong></p><p>${scenario.direction}</p>${scenario.priorities.length?`<h3>Practice priorities from your selections</h3><ol>${scenario.priorities.map(item=>`<li><strong>${item.question}</strong> ${item.coaching}</li>`).join("")}</ol>`:""}</article>
    <article class="summary-card"><h2>My Three Next Steps</h2><ol>${actions.map(x=>`<li>${x}</li>`).join("")}</ol></article>
    <div class="notice"><strong>Final reminder:</strong> Presence supports substance; it does not replace preparation. Use honest examples, connect experience to employer needs, and ask thoughtful questions.</div>`;
}

function showPage(id,{updateHistory=true,remember=true}={}){if(!pages.includes(id))id="home";document.querySelectorAll(".page").forEach(p=>p.classList.toggle("active",p.dataset.pagePanel===id));document.querySelectorAll(".course-nav button").forEach(b=>b.classList.toggle("active",b.dataset.page===id));const i=pages.indexOf(id),previous=document.getElementById("previousPage"),next=document.getElementById("nextPage"),final=i===pages.length-1;document.getElementById("pageCount").textContent=`${i+1} of ${pages.length}`;previous.disabled=i===0;previous.dataset.target=pages[Math.max(0,i-1)];next.disabled=false;next.dataset.target=final?"academy-home":pages[i+1];next.textContent=final?"Course Complete →":"Next →";next.setAttribute("aria-label",final?"Course complete, return to Academy Home":"Go to the next course page");if(updateHistory)history.replaceState(null,"",`#${id}`);if(remember&&workbook.lastPage!==id){workbook.lastPage=id;save({quiet:true})}window.scrollTo({top:0,behavior:"smooth"})}
function download(name,text,type="application/json"){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}

loadSaved();render();
document.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>showPage(b.dataset.page));document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>showPage(b.dataset.go));document.getElementById("previousPage").onclick=e=>showPage(e.currentTarget.dataset.target);document.getElementById("nextPage").onclick=e=>{const target=e.currentTarget.dataset.target;if(target==="academy-home")window.location.href="../index.html";else showPage(target)};
document.getElementById("downloadWorkbook").onclick=()=>download("HFTB_Interview_Skills_Workbook.json",JSON.stringify(workbook,null,2));document.getElementById("loadWorkbook").onclick=()=>document.getElementById("workbookFile").click();document.getElementById("workbookFile").onchange=async e=>{try{workbook=normalizeWorkbook(JSON.parse(await e.target.files[0].text()));save();render();showPage("summary")}catch{alert("That file is not a valid Interview Skills workbook.")}e.target.value=""};
document.getElementById("startFresh").onclick=()=>{if(confirm("Clear all Interview Skills answers stored in this browser?")){workbook=emptyWorkbook();try{localStorage.removeItem(storageKey)}catch{}render();setSaveNotice("Answers cleared. New answers will save automatically in this browser.");showPage("home",{remember:false})}};
document.getElementById("printSummary").onclick=()=>window.print();document.getElementById("downloadSummary").onclick=()=>download("HFTB_My_Interview_Readiness_Summary.txt",`HOMES FOR THE BRAVE\nINTERVIEW PRESENCE & CONFIDENCE\n\n${document.getElementById("summaryContent").innerText}`,"text/plain");
const requested=location.hash.slice(1),initial=pages.includes(requested)?requested:(restoredSession&&pages.includes(workbook.lastPage)?workbook.lastPage:"home");showPage(initial,{updateHistory:Boolean(requested),remember:false});
if(!storageWorks)setSaveNotice("Your browser is blocking local saving. Use Download Backup before leaving this course.","error");else if(restoredSession)setSaveNotice(`Welcome back — restored ${answerCount()} saved responses from ${workbook.updatedAt?new Date(workbook.updatedAt).toLocaleString():"an earlier visit"}. You are continuing where you stopped.`,"restored");
